/**
 * Per-transaction statement to attach for a partner. Holiday lines (lagged) show the note instead
 * of the rate: that rate is the vendor's B-2 value and may not leave the company (ovsettle/fxq-b2).
 */
public static String partnerDetail(String partnerId, LocalDate from, LocalDate to,
                                   List<SettledTxn> txns, DataFiles data) {
    String name = data.partner(partnerId).map(p -> p.name()).orElse("?");
    StringBuilder sb = new StringBuilder(String.format("%s %s 정산 내역 (%s ~ %s)%n", partnerId, name, from, to));
    long krw = 0;
    for (SettledTxn s : txns) {
        Transaction t = s.txn();
        String rate = s.lagged() ? "휴장일·정산 기준 환율 적용"
                : ("JPY".equals(t.currency()) ? "100엔당 " : "") + Money.rate(s.rate());
        sb.append(String.format("%s  %s  %s %s  %s  %s%n", s.date(), t.id(), t.currency(),
                foreign(t.signedAmount(), t.currency()), rate, Money.won(s.krw())));
        krw += s.krw();
    }
    sb.append(String.format("합계 %d건 %s%n", txns.size(), Money.won(krw)));
    return sb.toString();
}

private static String foreign(BigDecimal amount, String currency) {
    String pattern = "JPY".equals(currency) ? "#,##0" : "#,##0.00";
    return new DecimalFormat(pattern, DecimalFormatSymbols.getInstance(Locale.ROOT)).format(amount);
}

